import {render,screen} from '@testing-library/react';
import {describe,it,expect} from 'vitest';
import {Content,Badge} from '../src/ui';
import {SystemHealthSchema} from '../src/schemas';
import {readSnapshotFile} from './snapshot-file';
// The fixture is the backend's actual read-only projection, generated by E2E setup.
const fixture=()=>SystemHealthSchema.parse(readSnapshotFile());
describe('evidence projection',()=>{
  it('renders source-derived phase state',()=>{const state=fixture();render(<Content name="Overview" state={state}/>);for(const phase of state.phases)expect(screen.getAllByText(phase.status).length).toBeGreaterThan(0);expect(screen.getByText('R4')).toBeInTheDocument();});
  it('never promotes unknown state',()=>{render(<Badge status="NOT_VERIFIED"/>);expect(screen.getByText('NOT_VERIFIED')).toBeInTheDocument();expect(screen.queryByText('PASS')).not.toBeInTheDocument();});
  it('keeps runtime evidence historical',()=>{render(<Content name="Runtime" state={fixture()}/>);expect(screen.getByText('HISTORICAL_CONTROLLED_RUNTIME')).toBeInTheDocument();expect(screen.getByText('NOT_VERIFIED')).toBeInTheDocument();});
  it('renders actual fixture receipt without production claim',()=>{const state=fixture();render(<Content name="Knowledge" state={state}/>);expect(screen.getByText('FIXTURE_EVIDENCE')).toBeInTheDocument();expect(screen.getByText(/Immutable invocation receipt/)).toBeInTheDocument();});
});
